mapper.select:

SELECT COUNT(1)
FROM im_conversation_member
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}

mapper.update:

UPDATE im_conversation_member
SET last_read_msg_id = #{lastReadMsgId}
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}

mapper.select:

SELECT m2.user_id
FROM im_conversation_member m1
         JOIN im_conversation_member m2
              ON m1.conversation_id = m2.conversation_id
WHERE m1.conversation_id = #{conversationId}
  AND m1.user_id = #{selfId}
  AND m2.user_id <> #{selfId}
    LIMIT 1
